// In DAO.sol
function withdrawRewardFor(address _account) noEther internal returns (bool _success) {
    if ((balanceOf(_account) * rewardAccount.accumulatedInput()) / totalSupply < paidOut[_account])
        throw;

    uint reward =
        (balanceOf(_account) * rewardAccount.accumulatedInput()) / totalSupply - paidOut[_account];
    if (!rewardAccount.payOut(_account, reward)) // External call via ManagedAccount.payOut
        throw;
    paidOut[_account] += reward; // State update happens here
    return true;
}

// In ManagedAccount.sol
function payOut(address _recipient, uint _amount) returns (bool) {
    if (msg.sender != owner || msg.value > 0 || (payOwnerOnly && _recipient != owner))
        throw;
    if (_recipient.call.value(_amount)()) { // External call before state update in DAO
        PayOut(_recipient, _amount);
        return true;
    } else {
        return false;
    }
}

function createTokenProxy(address _tokenHolder) returns (bool success) {
    if (now < closingTime && msg.value > 0
        && (privateCreation == 0 || privateCreation == msg.sender)) {

        uint token = (msg.value * 20) / divisor();
        extraBalance.call.value(msg.value - token)(); // Unchecked return value
        balances[_tokenHolder] += token;
        totalSupply += token;
        weiGiven[_tokenHolder] += msg.value;
        CreatedToken(_tokenHolder, token);
        if (totalSupply >= minTokensToCreate && !isFueled) {
            isFueled = true;
            FuelingToDate(totalSupply);
        }
        return true;
    }
    throw;
}

function divisor() constant returns (uint divisor) {
    // The number of (base unit) tokens per wei is calculated
    // as `msg.value` * 20 / `divisor`
    // The fueling period starts with a 1:1 ratio
    if (closingTime - 2 weeks > now) {
        return 20;
    // Followed by 10 days with a daily creation rate increase of 5%
    } else if (closingTime - 4 days > now) {
        return (20 + (now - (closingTime - 2 weeks)) / (1 days)); // Integer division
    // The last 4 days there is a constant creation rate ratio of 1:1.5
    } else {
        return 30;
    }
}

